+      expect(await stdoutOf('cat <<< "hi there"'), 'hi there\n');
+    });
+
+    test('here-string expands unquoted words', () async {
+      await stdoutOf('export HS=42');
+      expect(await stdoutOf('cat <<< \$HS'), '42\n');
+    });
+  });
+}
