+      await stdoutOf('cat <<EOF > /tmp/hd.txt\nline1\nline2\nEOF');
+      expect(await stdoutOf('cat /tmp/hd.txt'), 'line1\nline2\n');
+    });
+
+    test('heredoc feeds a pipeline', () async {
+      expect(await stdoutOf('cat <<EOF | grep b\nab\ncd\nEOF'), 'ab\n');
+    });
+
