Future<Result<_StageResult, ExecutionError>> _runPipeline(
  Pipeline pipeline,
  ShellExecOptions? options, [
  int depth = 0,
]) async {
  List<int>? pipeInput;
  var stageResult = const _StageResult(stdout: [], stderr: [], exitCode: 0);

