    // statements in the same command line (e.g. `export A=1 && echo $A`)
    // are visible.
    final expansion = await expandShellStage(
      pipeline.stages[i],
      _effectiveEnv(options),
      (source) => _scriptRunner.substitute(source, options, depth),
    );
