      stdinText = read.valueOrNull;
    } else if (pipeInput != null) {
      stdinText = utf8.decode(pipeInput, allowMalformed: true);
    }

    stageResult = await _runCommand(
      stage.command,
      stage.args,
      options,
      cwd,
      stdinText,
    );

