          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('EOF'),
          ),
        ),
      );
    });
  });

  group('probe: CRLF heredoc', () {
    test('body with \r\n line endings', () {
      final r = redirectOf('cat <<EOF\r\nbody\r\nEOF\r\n');
      expect(r?.body, 'body\n');
    });
  });

  group('probe: glob guard regression candidates', () {
    const shouldParse = <String>[
      'rg pattern . --glob "*.dart"', // quoted glob flag value
      'grep -r "a*b" .', // quoted
      'tar czf out.tgz .', // no glob
      'echo done', // reserved-word substring not in command position
      'findfile x', // reserved word as substring
      'git log --format=%h', // braces absent
      'jq -c "{a: .b}" f.json', // quoted braces
      'stat -c [%q-%s] f', // bracket (pinned)
      'expr 6 \\* 7', // escaped star
    ];
    for (final c in shouldParse) {
      test('parses: $c', () {
        expect(() => parseShellScript(c), returnsNormally);
      });
    }
    const shouldReject = <String>[
      'ls *.dart',
      'grep x --include=*.py .', // unquoted glob in flag value — rejected?
    ];
    for (final c in shouldReject) {
      test('rejected: $c', () {
        expect(() => parseShellScript(c), throwsA(isA<ShellParseException>()));
      });
    }
  });

  group('probe: here-string extra words', () {
    test('cat <<< a b', () {
      final script = parseShellScript('cat <<< a b');
      final stage =
          (script.nodes.single as ScriptPipeline).pipeline.stages.single;
      expect(stage.redirects.single.kind, RedirectKind.hereString);
      expect(stage.redirects.single.target, 'a');
      expect(stage.args, ['b']);
