import 'package:fa/sandbox/shell_parser.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  Redirect? firstRedirect(String input) {
    final script = parseShellScript(input);
    final node = script.nodes.first as ScriptPipeline;
    final stage = node.pipeline.stages.first;
    return stage.redirects.isEmpty ? null : stage.redirects.first;
  }

  group('probe: heredoc with && on the command line (POSIX-legal)', () {
    test('cat <<EOF && echo x', () {
      final script = parseShellScript('cat <<EOF && echo x\nbody\nEOF');
      expect(script.nodes, hasLength(2));
      final stage = (script.nodes.first as ScriptPipeline).pipeline.stages.first;
      expect(stage.redirects.single.body, 'body\n');
      expect((script.nodes[1] as ScriptPipeline).pipeline.stages.single.command,
          'echo');
    });
  });

  group('probe: heredoc body trailing content', () {
    test('delimiter at EOF without trailing newline still terminates', () {
      final r = firstRedirect('cat <<EOF\nbody\nEOF');
      expect(r?.body, 'body\n');
    });
    test('EOFX never matches delimiter EOF -> unterminated', () {
      expect(
        () => parseShellScript('cat <<EOF\nbody\nEOFX'),
        throwsA(isA<ShellParseException>()),
      );
    });
  });

  group('probe: heredoc delimiter word quoted with mixed quotes', () {
    test('cat <<"E"OF — partial quoting disables expansion (POSIX)', () {
      final r = firstRedirect('cat <<"E"OF\n\$V\nEOF');
      expect(r?.expandable, isFalse);
      expect(r?.body, '\$V\n');
    });
  });
}
