  if (!isVarStart) {
    buffer.write('\$');
    return i + 1;
  }
  var j = i + 1;
  while (j < input.length) {
    final c = input.codeUnitAt(j);
    final isVarChar =
        (c >= 65 && c <= 90) ||
        (c >= 97 && c <= 122) ||
        (c >= 48 && c <= 57) ||
        c == 95;
    if (!isVarChar) break;
    j++;
  }
  buffer.write(env[input.substring(i + 1, j)] ?? '');
  return j;
