      stage.command,
      stage.args,
      options,
      cwd,
      stdinText,
    );

    if (stdoutFile != null) {
      await _writeRedirect(stdoutFile, stageResult.stdout, appendStdout, cwd);
    } else {
      final text = utf8.decode(stageResult.stdout, allowMalformed: true);
