    test('echo x 2>(tee y)', () {
      try {
        parseShellScript('echo x 2>(tee y)');
        // ignore: avoid_print
        print('2>(...) PARSED (guard missed)');
      } on ShellParseException catch (e) {
        // ignore: avoid_print
        print('2>(...) throws: ${e.message}');
      }
    });
  });

