+    });
+
+    test('quoted delimiter keeps the body literal', () async {
+      await stdoutOf('export HD_NAME=world');
+      expect(
+        await stdoutOf("cat <<'EOF'\nhello \$HD_NAME\nEOF"),
+        'hello \$HD_NAME\n',
