+import 'package:flutter_test/flutter_test.dart';
+
+void main() {
+  late MemoryExecutionEnv env;
+
+  setUp(() {
+    final shell = MemoryShell();
+    env = MemoryExecutionEnv(cwd: '/', shell: shell);
+    shell.attach(env);
+  });
