import 'package:fa/sandbox/shell_parser.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  group('round-2: rework fixes (eb001d642)', () {
    test('fd-prefixed process substitution 2>( is rejected', () {
      expect(
        () => parseShellScript('echo x 2>(tee y)'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('process substitution'),
          ),
        ),
      );
    });

    test('fd-prefixed process substitution 2<( is rejected', () {
      expect(
        () => parseShellScript('cat 2<(echo x)'),
        throwsA(isA<ShellParseException>()),
      );
    });

    test('3<<<word gets the precise fd-prefixed here-string error', () {
      expect(
        () => parseShellScript('cat 3<<<word'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('fd-prefixed here-strings'),
          ),
        ),
      );
    });

    test('X=1 <<EOF (bare assignment + heredoc) is rejected', () {
      expect(
        () => parseShellScript('X=1 <<EOF\nbody\nEOF'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('bare assignment'),
          ),
        ),
      );
    });

    test('A=1 B=2 (assignments only, no redirect) still parses', () {
      expect(() => parseShellScript('A=1 B=2'), returnsNormally);
    });

    test('plain X=1 still parses', () {
      expect(() => parseShellScript('X=1'), returnsNormally);
    });

    test('2>> and 2< still parse (guard does not over-fire)', () {
      expect(() => parseShellScript('echo x 2>>f'), returnsNormally);
      expect(() => parseShellScript('cat 0<f'), returnsNormally);
    });
  });

  group('round-1 regression probes (must keep passing)', () {
    Redirect? firstRedirect(String input) {
      final script = parseShellScript(input);
      final node = script.nodes.first as ScriptPipeline;
      final stage = node.pipeline.stages.first;
      return stage.redirects.isEmpty ? null : stage.redirects.first;
    }

    test('heredoc with && on the command line', () {
      final script = parseShellScript('cat <<EOF && echo x\nbody\nEOF');
      final stage =
          (script.nodes.first as ScriptPipeline).pipeline.stages.first;
      expect(stage.redirects.single.body, 'body\n');
    });

    test('two heredocs on one command (last wins)', () {
      final stage =
          (parseShellScript('cat <<A <<B\nfirst\nA\nsecond\nB').nodes.first
                  as ScriptPipeline)
              .pipeline
              .stages
              .single;
      expect(stage.redirects, hasLength(2));
      expect(stage.redirects[1].body, 'second\n');
    });

    test('CRLF heredoc body', () {
      expect(firstRedirect('cat <<EOF\r\nbody\r\nEOF\r\n')?.body, 'body\n');
    });

    test('quoted glob/tilde/brace args still parse', () {
      expect(
        () => parseShellScript("find /proj -name '*.dart'"),
        returnsNormally,
      );
      expect(() => parseShellScript('stat -c [%q-%s] f'), returnsNormally);
      expect(() => parseShellScript('expr 6 \\* 7'), returnsNormally);
    });
  });
}
