      expect(
        () => parseShellScript('cat 3<<<word'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('fd-prefixed here-strings'),
          ),
        ),
      );
    });

    test('X=1 <<EOF (bare assignment + heredoc) is rejected', () {
      expect(
        () => parseShellScript('X=1 <<EOF\nbody\nEOF'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('bare assignment'),
          ),
        ),
      );
    });

    test('A=1 B=2 (assignments only, no redirect) still parses', () {
      expect(() => parseShellScript('A=1 B=2'), returnsNormally);
    });

    test('plain X=1 still parses', () {
      expect(() => parseShellScript('X=1'), returnsNormally);
    });

    test('2>> and 2< still parse (guard does not over-fire)', () {
      expect(() => parseShellScript('echo x 2>>f'), returnsNormally);
      expect(() => parseShellScript('cat 0<f'), returnsNormally);
    });
  });

