import 'package:fa/sandbox/shell_parser.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  Redirect? redirectOf(String input) {
    final script = parseShellScript(input);
    final node = script.nodes.single as ScriptPipeline;
    final stage = node.pipeline.stages.single;
    return stage.redirects.isEmpty ? null : stage.redirects.single;
  }

  group('probe: heredoc with && on the command line (POSIX-legal)', () {
    test('cat <<EOF && echo x', () {
      // Real shells accept this; expect body capture to work.
      final script = parseShellScript('cat <<EOF && echo x\nbody\nEOF');
      final node = script.nodes.single as ScriptPipeline;
      final stage = node.pipeline.stages.first;
      expect(stage.redirects.single.body, 'body\n');
    });
  });

  group('probe: two heredocs on one command (last wins)', () {
    test('cat <<A <<B', () {
      final script = parseShellScript('cat <<A <<B\nfirst\nA\nsecond\nB');
      final stage =
          (script.nodes.single as ScriptPipeline).pipeline.stages.single;
      expect(stage.redirects, hasLength(2));
      expect(stage.redirects[0].body, 'first\n');
      expect(stage.redirects[1].body, 'second\n');
    });
  });

  group('probe: fd-prefixed here-string 3<<<word', () {
    test('cat 3<<<x', () {
      try {
        final r = redirectOf('cat 3<<<x');
        // ignore: avoid_print
        print('3<<< parsed as kind=${r?.kind} fd=${r?.fd} target=${r?.target}');
      } on ShellParseException catch (e) {
        // ignore: avoid_print
        print('3<<< throws: ${e.message}');
      }
    });
  });

  group('probe: fd-prefixed process substitution 2>(tee y)', () {
    test('echo x 2>(tee y)', () {
      try {
        parseShellScript('echo x 2>(tee y)');
        // ignore: avoid_print
        print('2>(...) PARSED (guard missed)');
      } on ShellParseException catch (e) {
        // ignore: avoid_print
        print('2>(...) throws: ${e.message}');
      }
    });
  });

  group('probe: heredoc body ending without trailing newline', () {
    test('no trailing newline after delimiter', () {
      final r = redirectOf('cat <<EOF\nbody\nEOF');
      expect(r?.body, 'body\n');
      final r2 = redirectOf('cat <<EOF\nbody\nEOFX');
      // delimiter line is the last line without \n; body keeps EOFX
      expect(r2?.body, 'body\nEOFX');
    });
  });

  group('probe: assignments with heredoc', () {
    test('X=1 <<EOF', () {
      try {
        parseShellScript('X=1 <<EOF\nbody\nEOF');
        // ignore: avoid_print
        print('X=1 <<EOF parses (assignment + orphan heredoc)');
      } on ShellParseException catch (e) {
        // ignore: avoid_print
        print('X=1 <<EOF throws: ${e.message}');
      }
    });
  });

  group('probe: unterminated inside if', () {
    test('if true; then cat <<EOF / body, no EOF', () {
      expect(
        () => parseShellScript('if true; then cat <<EOF\nbody'),
        throwsA(
          isA<ShellParseException>().having(
            (e) => e.message,
            'message',
            contains('EOF'),
          ),
        ),
      );
    });
  });

  group('probe: CRLF heredoc', () {
    test('body with \r\n line endings', () {
      final r = redirectOf('cat <<EOF\r\nbody\r\nEOF\r\n');
      expect(r?.body, 'body\n');
    });
  });

  group('probe: glob guard regression candidates', () {
    const shouldParse = <String>[
      'rg pattern . --glob "*.dart"', // quoted glob flag value
      'grep -r "a*b" .', // quoted
      'tar czf out.tgz .', // no glob
      'echo done', // reserved-word substring not in command position
      'findfile x', // reserved word as substring
      'git log --format=%h', // braces absent
      'jq -c "{a: .b}" f.json', // quoted braces
      'stat -c [%q-%s] f', // bracket (pinned)
      'expr 6 \\* 7', // escaped star
    ];
    for (final c in shouldParse) {
      test('parses: $c', () {
        expect(() => parseShellScript(c), returnsNormally);
      });
    }
    const shouldReject = <String>[
      'ls *.dart',
      'grep x --include=*.py .', // unquoted glob in flag value — rejected?
    ];
    for (final c in shouldReject) {
      test('rejected: $c', () {
        expect(() => parseShellScript(c), throwsA(isA<ShellParseException>()));
      });
    }
  });

  group('probe: here-string extra words', () {
    test('cat <<< a b', () {
      final script = parseShellScript('cat <<< a b');
      final stage =
          (script.nodes.single as ScriptPipeline).pipeline.stages.single;
      expect(stage.redirects.single.kind, RedirectKind.hereString);
      expect(stage.redirects.single.target, 'a');
      expect(stage.args, ['b']);
    });
  });

  group('probe: heredoc delimiter word quoted with mixed quotes', () {
    test('cat <<"E"OF — partial quoting disables expansion (POSIX)', () {
      final r = redirectOf('cat <<"E"OF\n\$V\nE OF?');
      // POSIX: any quoted part of the delimiter disables expansion.
      expect(r?.expandable, isFalse);
    });
  });

  group('probe: `<<` inside double quotes is literal', () {
    test('echo "a<<b"', () {
      expect(() => parseShellScript('echo "a<<b"'), returnsNormally);
    });
  });

  group('probe: backtick arithmetic detection gap', () {
    test('echo `expr 1 + 2` stays legal', () {
      expect(() => parseShellScript('echo `expr 1 + 2`'), returnsNormally);
    });
    test('echo "\$((1+2))" inside double quotes rejected', () {
      expect(
        () => parseShellScript('echo "\$((1+2))"'),
        throwsA(isA<ShellParseException>()),
      );
    });
  });
}
