    if (expanded.isErr) return Err(expanded.errorOrNull!);
    final result = expanded.valueOrNull!;
    if (result.hadSubstitution && !stage.isQuoted(k)) {
      argv.addAll(splitSubstitutionFields(result.text));
    } else {
      argv.add(result.text);
    }
  }
